INSERT INTO destination (nom,pays,continent,description,description_longue,points_forts,meilleure_periode,latitude,longitude,photo_url,categorie) VALUES
('Nice','France','Europe','Joyau de la Côte d''Azur.','Joyau de la Côte d''Azur, Nice déroule sa Promenade des Anglais le long d''une mer azur. Vieille ville colorée, marché aux fleurs et lumière méditerranéenne en font une escale envoûtante. Le carnaval et les collines de Cimiez complètent le tableau.','Promenade des Anglais|Vieux Nice|Colline du Château|Marché aux fleurs|Musée Matisse','Mai à septembre',43.7102,7.262,'','plage'),
('Lyon','France','Europe','Capitale de la gastronomie française.','Capitale de la gastronomie, Lyon séduit par son Vieux Lyon Renaissance et ses traboules secrètes. Entre Rhône et Saône, la ville mêle patrimoine UNESCO et scène culinaire bouillonnante. La basilique de Fourvière veille sur les toits.','Vieux Lyon & traboules|Basilique de Fourvière|Presqu''île|Bouchons lyonnais|Parc de la Tête d''Or','Avril à octobre & décembre (Fête des Lumières)',45.764,4.8357,'','culture'),
('Bordeaux','France','Europe','Cité du vin classée à l''UNESCO.','Élégante cité du vin classée à l''UNESCO, Bordeaux aligne ses façades de pierre blonde le long de la Garonne. Le miroir d''eau, les quais réaménagés et les châteaux viticoles alentour en font une destination raffinée. Art de vivre et grands crus au rendez-vous.','Place de la Bourse & miroir d''eau|Cité du Vin|Quais de la Garonne|Vignobles du Médoc|Rue Sainte-Catherine','Mai à octobre',44.8378,-0.5792,'','culture'),
('Marseille','France','Europe','Cité phocéenne au caractère solaire.','Cité phocéenne au caractère solaire, Marseille vibre autour de son Vieux-Port et de ses calanques turquoise. Notre-Dame de la Garde domine la ville, entre influences méditerranéennes et énergie populaire. Bouillabaisse et îles du Frioul prolongent l''évasion.','Vieux-Port|Notre-Dame de la Garde|Calanques|Le Panier|MuCEM','Mai à septembre',43.2965,5.3698,'','plage'),
('Madrid','Espagne','Europe','Capitale animée et chaleureuse de l''Espagne.','Capitale animée et chaleureuse, Madrid bat au rythme de ses places monumentales et de ses musées d''exception. Le Prado, le Retiro et les tavernes à tapas composent un art de vivre intense. La vie nocturne y est légendaire.','Musée du Prado|Plaza Mayor|Parc du Retiro|Palais Royal|Marché de San Miguel','Avril à juin & septembre à octobre',40.4168,-3.7038,'','ville'),
('Séville','Espagne','Europe','Capitale envoûtante de l''Andalousie.','Capitale de l''Andalousie, Séville enivre par son flamenco, ses patios fleuris et son Alcázar mauresque. La Giralda et la cathédrale témoignent d''un riche passé. Chaleur, oranges amères et ferveur des fêtes y règnent.','Alcázar de Séville|Cathédrale & Giralda|Plaza de España|Quartier de Santa Cruz|Spectacle de flamenco','Mars à mai & octobre',37.3891,-5.9845,'','culture'),
('Valence','Espagne','Europe','Entre patrimoine gothique et architecture futuriste.','Troisième ville d''Espagne, Valence marie patrimoine gothique et architecture futuriste. La Cité des Arts et des Sciences côtoie un vieux centre vivant et de longues plages. Berceau de la paella, elle conjugue mer et modernité.','Cité des Arts et des Sciences|Vieille ville & cathédrale|Marché Central|Plage de la Malvarrosa|Jardins du Turia','Mars à juin & septembre à octobre',39.4699,-0.3763,'','ville'),
('Grenade','Espagne','Europe','L''Alhambra au pied de la Sierra Nevada.','Au pied de la Sierra Nevada, Grenade abrite l''Alhambra, palais nasride d''une beauté inégalée. Le quartier de l''Albaicín et les cuevas du Sacromonte composent une atmosphère envoûtante. Tapas gratuites et héritage maure font sa renommée.','Alhambra & Generalife|Quartier de l''Albaicín|Mirador San Nicolás|Cathédrale|Sacromonte','Avril à juin & septembre à octobre',37.1773,-3.5986,'','culture'),
('Venise','Italie','Europe','La cité des canaux, magique et unique.','Cité lacustre sans pareille, Venise se découvre au fil de ses canaux et de ses ponts. Place Saint-Marc, gondoles et palais gothiques composent un décor théâtral. Une ville-musée flottante, magique hors saison.','Place Saint-Marc|Pont du Rialto|Balade en gondole|Basilique Saint-Marc|Îles de Murano et Burano','Avril à juin & septembre à octobre',45.4408,12.3155,'','culture'),
('Florence','Italie','Europe','Le berceau de la Renaissance.','Berceau de la Renaissance, Florence concentre un patrimoine artistique vertigineux. Le Duomo, les Offices et le Ponte Vecchio racontent les Médicis. Toscane, art et gastronomie s''y conjuguent à merveille.','Cathédrale (Duomo)|Galerie des Offices|Ponte Vecchio|David de Michel-Ange|Palazzo Pitti','Avril à juin & septembre à octobre',43.7696,11.2558,'','culture'),
('Milan','Italie','Europe','Capitale de la mode et du design.','Capitale italienne de la mode et du design, Milan allie gothique flamboyant et élégance contemporaine. Le Duomo de marbre et la Galleria Vittorio Emanuele côtoient boutiques de luxe et aperitivos. La Cène de Vinci y est jalousement gardée.','Duomo de Milan|Galleria Vittorio Emanuele II|La Cène de Léonard de Vinci|Quartier de Brera|Château des Sforza','Avril à juin & septembre à octobre',45.4642,9.19,'','ville'),
('Naples','Italie','Europe','Bouillonnante, sur sa baie dominée par le Vésuve.','Bouillonnante et authentique, Naples règne sur sa baie dominée par le Vésuve. Berceau de la pizza, elle mêle ruelles populaires, trésors baroques et accès à Pompéi. Une intensité méditerranéenne unique.','Centre historique|Vésuve|Pompéi à proximité|Pizza napolitaine|Front de mer (Lungomare)','Avril à juin & septembre à octobre',40.8518,14.2681,'','ville'),
('Cinque Terre','Italie','Europe','Cinq villages colorés sur la Riviera ligure.','Cinq villages accrochés aux falaises de la Riviera ligure, les Cinque Terre enchantent par leurs maisons colorées plongeant dans la mer. Sentiers panoramiques, vignobles en terrasses et criques composent un paradis classé à l''UNESCO.','Village de Manarola|Sentier Azur|Vernazza|Vignobles en terrasses|Baignade dans les criques','Mai à septembre',44.1461,9.6439,'','plage'),
('Osaka','Japon','Asie','La capitale gourmande et festive du Japon.','Capitale gourmande du Japon, Osaka déborde d''énergie autour de Dotonbori et de ses enseignes lumineuses. Château majestueux, street food (takoyaki, okonomiyaki) et habitants chaleureux en font un contraste vivant avec Kyoto. La nuit y est festive.','Château d''Osaka|Quartier de Dotonbori|Street food|Aquarium Kaiyukan|Temple Shitennoji','Mars-avril & octobre-novembre',34.6937,135.5023,'','ville'),
('Hiroshima','Japon','Asie','Ville de mémoire et de paix.','Ville de mémoire et de paix, Hiroshima renaît autour de son Dôme et de son parc du Mémorial. À proximité, le torii flottant de Miyajima offre l''une des vues les plus célèbres du Japon. Émotion et sérénité s''y mêlent.','Parc du Mémorial de la Paix|Dôme de Genbaku|Île de Miyajima & torii flottant|Château d''Hiroshima|Okonomiyaki local','Mars-avril & octobre-novembre',34.3853,132.4553,'','culture'),
('Nara','Japon','Asie','Première capitale impériale, daims en liberté.','Première capitale impériale du Japon, Nara est célèbre pour ses daims en liberté et son Grand Bouddha. Temples millénaires et parc paisible en font une excursion enchanteresse. L''âme spirituelle du pays s''y ressent.','Temple Todai-ji & Grand Bouddha|Daims du parc de Nara|Sanctuaire Kasuga|Temple Kofuku-ji|Jardin Isuien','Mars-avril & octobre-novembre',34.6851,135.8048,'','culture'),
('Sapporo','Japon','Asie','Capitale d''Hokkaido, neige et ramen.','Capitale de l''île d''Hokkaido, Sapporo est réputée pour son festival de neige et ses stations de ski poudreuses. Bière locale, ramen au miso et sources chaudes réchauffent les hivers rigoureux. Nature généreuse en toute saison.','Festival de la neige|Ski à Niseko (proche)|Parc Odori|Ramen au miso|Sources chaudes (onsen)','Décembre à février (neige) & juin à août',43.0618,141.3545,'','montagne');
